import asyncio
import base64
import io
import sys
import pygame

# Initialize Pygame
pygame.init()
pygame.font.init()

screen = pygame.display.set_mode((600, 400))
pygame.display.set_caption("2D Platformer")
clock = pygame.time.Clock()

score_font = pygame.font.SysFont("arial", 24, bold=True)

# Embed the playable character as a Base64-encoded image.
# Replace the value below with your own Base64 string. Both raw Base64 and
# data URLs such as "data:image/png;base64,..." are supported.
PLAYER_IMAGE_BASE64 = ""

try:
    encoded_image = PLAYER_IMAGE_BASE64
    if encoded_image.startswith("data:"):
        encoded_image = encoded_image.split(",", 1)[1]

    image_bytes = base64.b64decode(encoded_image, validate=True)
    player_image = pygame.image.load(io.BytesIO(image_bytes)).convert_alpha()
    player_image = pygame.transform.scale(player_image, (50, 50))
except Exception as e:
    print(f"Error loading Base64 player image: {e}")
    # Visible red placeholder if the Base64 string is empty or invalid.
    player_image = pygame.Surface((50, 50))
    player_image.fill((255, 0, 0))

player_rect = pygame.Rect(50, 320, 50, 50)

# Movement & Physics
player_dy = 0
gravity = 0.5
jump_speed = -11
on_ground = False

# Layout Setup
platforms = [
    pygame.Rect(0, 370, 600, 30),
    pygame.Rect(40, 290, 130, 20),
    pygame.Rect(220, 220, 140, 20),
    pygame.Rect(420, 160, 130, 20),
    pygame.Rect(90, 120, 110, 20),
]

# Cupcakes
try:
    cupcake_image = pygame.image.load("cupcake.png").convert_alpha()
    cupcake_image = pygame.transform.scale(cupcake_image, (30, 30))
except FileNotFoundError:
    cupcake_image = pygame.Surface((30, 30), pygame.SRCALPHA)
    cupcake_image.fill((255, 192, 203))

cupcakes = [
    pygame.Rect(90, 255, 30, 30),
    pygame.Rect(275, 185, 30, 30),
    pygame.Rect(470, 125, 30, 30),
    pygame.Rect(130, 85, 30, 30),
]

score = 0

async def main():
    global player_dy, on_ground, score

    running = True
    while running:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False

        keys = pygame.key.get_pressed()

        # Movement
        dx = 0
        if keys[pygame.K_LEFT]:
            dx -= 5
        if keys[pygame.K_RIGHT]:
            dx += 5

        player_rect.x += dx
        for platform in platforms:
            if player_rect.colliderect(platform):
                if dx > 0:
                    player_rect.right = platform.left
                if dx < 0:
                    player_rect.left = platform.right

        # Prevent the player from walking off the platform they are standing on.
        if on_ground:
            for platform in platforms:
                standing_on_platform = (
                    player_rect.bottom == platform.top
                    and player_rect.right > platform.left
                    and player_rect.left < platform.right
                )
                if standing_on_platform:
                    player_rect.left = max(player_rect.left, platform.left)
                    player_rect.right = min(player_rect.right, platform.right)
                    break

        # Jump
        if keys[pygame.K_UP] and on_ground:
            player_dy = jump_speed
            on_ground = False

        # Physics
        player_dy += gravity
        player_rect.y += player_dy

        on_ground = False
        for platform in platforms:
            if player_rect.colliderect(platform):
                if player_dy > 0:
                    player_rect.bottom = platform.top
                    player_dy = 0
                    on_ground = True
                elif player_dy < 0:
                    player_rect.top = platform.bottom
                    player_dy = 0

        # Collectibles
        for cupcake in cupcakes[:]:
            if player_rect.colliderect(cupcake):
                cupcakes.remove(cupcake)
                score += 1

        # Render
        screen.fill((67, 21, 103))

        for platform in platforms:
            pygame.draw.rect(screen, (75, 85, 130), platform)

        for cupcake in cupcakes:
            screen.blit(cupcake_image, (cupcake.x, cupcake.y))

        screen.blit(player_image, (player_rect.x, player_rect.y))

        score_surface = score_font.render(f"Cupcakes: {score}", True, (255, 255, 255))
        screen.blit(score_surface, (20, 20))

        pygame.display.flip()
        clock.tick(60)
        await asyncio.sleep(0)

    pygame.quit()


asyncio.run(main())
sys.exit()